module JobScheduler (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [15:0] times [0:7],\n    output reg [5:0] result,\n    output reg done\n);\n\n    localparam [2:0] S_IDLE = 3'd0, S_SET_I = 3'd1, S_FIND_J = 3'd2, S_NEXT_L = 3'd3, S_UPDATE_DP = 3'd4;\n\n    reg [2:0] state;\n    reg [2:0] i;\n    reg [1:0] L_state;\n    reg [2:0] j;\n    reg [5:0] dp [0:7];\n    reg [15:0] time_i;\n    reg [16:0] add_val;\n    reg [5:0] candidate_max;\n    reg [5:0] candidate;\n    reg [5:0] dp_next;\n\n    integer k;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            result <= 6'd0;\n            for (k = 0; k < 8; k = k + 1) dp[k] <= 6'd0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= S_SET_I;\n                        i <= (N > 0) ? N - 1 : 3'd0;\n                        dp_next <= 6'd0;\n                    end\n                end\n\n                S_SET_I: begin\n                    time_i <= times[i];\n                    candidate_max <= dp_next;\n                    L_state <= 2'd0;\n                    state <= S_FIND_J;\n                    j <= i + 3'd1;\n                end\n\n                S_FIND_J: begin\n                    add_val <= time_i + (16'd2 + L_state);\n                    if (j < N && {16'b0, times[j]} >= add_val) begin\n                        candidate <= (6'd2 + L_state) + dp[j];\n                        state <= S_NEXT_L;\n                    end else if (j < N) begin\n                        j <= j + 3'd1;\n                    end else begin\n                        candidate <= (6'd2 + L_state);\n                        state <= S_NEXT_L;\n                    end\n                end\n\n                S_NEXT_L: begin\n                    if (candidate > candidate_max) candidate_max <= candidate;\n                    if (L_state == 2'd2) begin\n                        dp[i] <= candidate_max;\n                        dp_next <= candidate_max;\n                        state <= S_UPDATE_DP;\n                    end else begin\n                        L_state <= L_state + 2'd1;\n                        j <= i + 3'd1;\n                        state <= S_FIND_J;\n                    end\n                end\n\n                S_UPDATE_DP: begin\n                    if (i == 3'd0) begin\n                        result <= candidate_max;\n                        done <= 1'b1;\n                        state <= S_IDLE;\n                    end else begin\n                        i <= i - 3'd1;\n                        state <= S_SET_I;\n                    end\n                end\n\n                default: state <= S_IDLE;\n            endcase\n        end\n    end\nendmodule